from lib import *
FV="Portions de fruits et légumes"
def fv(n): return (FV,f"Portions de fruits et légumes par portion : {n}")
FZ="Instructions de congélation : "
recs=[
R(7046954,"Compote de pommes et de canneberges",
"Une sauce rapide et facile pour accompagner votre repas de Noël.",
"6","53 g",
["2 pommes","2 cuillères à soupe bombées de sauce aux canneberges","1 cuillère à soupe de canneberges séchées"],
["Épépinez les pommes et hachez-les grossièrement, puis mettez-les dans une casserole avec un filet d'eau. Ajoutez la sauce aux canneberges et les canneberges séchées.","Faites chauffer doucement en remuant régulièrement pendant 5 à 6 minutes, jusqu'à ce que les pommes soient ramollies."],
["Conservez au réfrigérateur.",FZ+"peut être congelé une fois cuit. Congelez en portions, puis décongelez et servez froid ou tiède.",fv(0)]),
R(7048524,"Fruits au barbecue",
"Une façon originale de revisiter les grillades, avec des fruits plutôt que des aliments salés.",
"6","195 g",
["3 poires, pelées, épépinées et coupées en quartiers","2 pommes, pelées, épépinées et coupées en quartiers","1 bonne pincée d'épices mélangées","5 tranches de melon miel, coupées en cubes (chair comestible 500 g)"],
["Mélangez simplement tous les ingrédients, répartissez-les entre 6 grands carrés de papier d'aluminium et fermez-les en papillotes.","Faites cuire sur les braises du barbecue environ 10 à 12 minutes et servez."],
["Pourquoi ne pas essayer une version tropicale : utilisez des mangues et de l'ananas.","Se marie bien avec différentes épices, comme la cannelle ou le gingembre moulu.",fv(2)]),
R(7050301,"Œufs cuits au four avec épinards, champignons et frites",
"Ce savoureux plat d'œufs cuits au four est une option végétarienne parfaite pour le déjeuner ou le souper. Les frites maison servies à côté sont idéales pour tremper dans les jaunes d'œufs. Cette recette a été sélectionnée en partenariat avec Slimming World.",
"4","578 g",
["750 g de pommes de terre farineuses, comme Maris Piper ou King Edward, coupées en frites","enduit de cuisson en aérosol faible en calories","1 oignon, coupé en petits dés","500 g de champignons châtaigne, finement tranchés","1 grosse pincée de muscade moulue","2 gousses d'ail, écrasées","600 g d'épinards surgelés, décongelés et bien pressés","75 g de yogourt grec nature sans gras et non sucré","4 gros œufs"],
["Préchauffez votre four à 200 °C/chaleur tournante 180 °C/thermostat 6. Étalez les frites en une seule couche sur une grande plaque de cuisson antiadhésive. Vaporisez de quelques pressions d'enduit de cuisson faible en calories et assaisonnez de poivre. Faites cuire 40 minutes, ou jusqu'à ce qu'elles soient dorées, en les retournant à mi-cuisson.","Pendant ce temps, vaporisez une grande poêle antiadhésive de quelques pressions d'enduit de cuisson faible en calories et placez-la à feu moyen-vif. Lorsqu'elle est chaude, ajoutez l'oignon et les champignons, et faites sauter 5 à 6 minutes, jusqu'à ce qu'ils soient ramollis et légèrement colorés. Incorporez la muscade et l'ail. Faites cuire 2 minutes, jusqu'à ce que ça dégage un parfum, puis ajoutez les épinards et remuez le tout jusqu'à ce que ce soit bien chaud à cœur. Retirez du feu et incorporez le yogourt, puis assaisonnez de poivre.","Répartissez le mélange entre 4 plats à tarte individuels, ou versez-le dans 1 grand plat à tarte. Faites 4 creux dans le mélange et cassez un œuf dans chacun. Garnissez d'un tour de moulin de poivre noir et faites cuire au four sur la grille du dessous pendant les 15 dernières minutes de cuisson des frites, ou jusqu'à ce que les blancs d'œufs soient pris. Répartissez les frites entre 4 assiettes et servez avec les œufs cuits au four."],
["Vous pouvez utiliser le yogourt nature de votre choix. Toutefois, cela modifiera les valeurs nutritionnelles et la texture du plat.","Les groupes à risque, comme les nourrissons, les enfants, les femmes enceintes, les personnes âgées et les personnes malades, devraient éviter les œufs mous, peu cuits ou crus, à moins de pouvoir garantir qu'ils sont produits selon le programme d'assurance qualité Lion code.",fv(3)]),
R(7052242,"Barres aux fruits de blé entier",
"Idéales pour les boîtes à lunch ou comme collation saine.",
"25","39 g",
["175 g de raisins secs","50 g de sucre","100 g de tartinade à base d'huile végétale","1 cuillère à café bombée d'épices mélangées","350 g de farine nature de grains entiers","50 g de noix de Grenoble hachées","50 g de dattes hachées"],
["Préchauffez le four à 180 ºC/thermostat 4 et graissez légèrement une plaque de cuisson de 19 cm x 28 cm.","Mettez les raisins secs, le sucre, la tartinade et les épices mélangées dans une casserole moyenne avec 200 ml d'eau.","Portez à ébullition, puis retirez du feu et laissez refroidir.","Dans un autre plat, mélangez les ingrédients restants, puis incorporez-les au mélange de raisins secs. Versez à la cuillère dans le moule préparé, lissez à 1 1/2 cm d'épaisseur, puis faites cuire au four 25 à 30 minutes.","Dès la sortie du four, marquez 25 barres.","Laissez refroidir et servez."],
["Essayez d'ajouter d'autres épices, comme la cannelle ou le gingembre moulu.","Vous pouvez aussi utiliser des fruits secs, comme un mélange de fruits secs, des raisins sultanines, des pruneaux ou des abricots.",FZ+"peut être congelé une fois cuit. Congelez en portions, puis décongelez et servez froid ou tiède.",fv(0)]),
R(7053704,"Pizza turque au chou-fleur avec Quorn et tzatziki",
"Le chou-fleur constitue une alternative saine et plus faible en glucides à la pâte à pizza traditionnelle.",
"4","478 g",
["Pour la base : 900 g/32 oz de chou-fleur, préparé en bouquets","1 petit oignon, finement haché","1 œuf moyen, battu","40 g/3 oz de fromage à la crème à 3 % de matières grasses, p. ex. Philadelphia léger, ou 40 g/3 oz de yogourt nature faible en gras","2 cuillères à soupe de farine de blé entier","1/4 cuillère à café de poivre noir fraîchement moulu","1 cuillère à café d'huile d'olive","Pour les garnitures : 1 cuillère à café d'huile d'olive","300 g/12 oz de hachis sans viande Quorn","2 cuillères à café de paprika fumé","1 cuillère à café de cumin moulu","1 cuillère à café de coriandre moulue","1/2 cuillère à café d'origan séché","1 gros concombre, la moitié râpée, la moitié coupée en petits dés","175 g/5 oz de tomates cerises, coupées en quartiers","2 cuillères à soupe de persil plat, haché","200 g/7 oz de yogourt nature faible en gras"],
["Pour la base : Préchauffez le four à 200 °C (180 ° chaleur tournante)/400 °F/thermostat 6. Graissez et tapissez de papier sulfurisé une grande plaque de cuisson ronde.","Placez les bouquets de chou-fleur dans un robot culinaire et actionnez par impulsions jusqu'à obtenir une texture de riz. Portez une grande casserole d'eau à ébullition et faites cuire le chou-fleur, couvert, 4 à 5 minutes, jusqu'à ce qu'il soit tendre.","Égouttez bien et rassemblez le chou-fleur dans un grand carré de mousseline ou d'étamine. Vous pouvez aussi utiliser un torchon propre. Enveloppez le chou-fleur dans la mousseline en forme de boule et tordez bien pour en extraire le plus d'eau possible.","Versez le chou-fleur essoré dans un bol et ajoutez l'œuf, le fromage à la crème, la farine et le poivre noir fraîchement moulu. Mélangez bien jusqu'à ce qu'une pâte grossière se forme.","Transférez la pâte de chou-fleur sur la plaque tapissée et étalez-la en un grand rond. Badigeonnez le dessus d'huile d'olive.","Faites cuire au four 25 à 35 minutes, jusqu'à ce qu'elle soit sèche au toucher et dorée de partout.","Pour les garnitures : Pendant ce temps, faites chauffer l'huile d'olive dans une sauteuse à feu moyen jusqu'à ce qu'elle soit chaude.","Ajoutez l'oignon et faites-le suer jusqu'à ce qu'il soit ramolli, environ 5 minutes. Incorporez le Quorn et faites cuire à feu un peu plus vif jusqu'à ce qu'il soit doré de partout, en l'émiettant avec une cuillère en bois.","Incorporez les épices et l'origan, et faites cuire encore 2 minutes. Retirez du feu et couvrez pour garder au chaud.","Sortez la base de chou-fleur du four lorsqu'elle est prête. Garnissez de Quorn, de concombre en dés, de tomates cerises et de persil haché.","Incorporez le concombre râpé au yogourt dans un petit bol. Déposez des cuillerées sur la pizza et servez le reste à part."],
["Remplacez le hachis Quorn de cette recette par des tranches de poivron ou d'aubergine grillés pour augmenter votre consommation de légumes.",fv(4)]),
R(7054837,"Salade de pois chiches et de thon",
"Des morceaux de thon rassasiants avec des pois chiches : ce plat est idéal pour un lunch à emporter.",
"2","458 g",
["le zeste râpé de 1/2 citron","1 pincée de poivre noir","20 ml d'huile d'olive extra vierge","1 petit oignon rouge, finement haché","180 g de tomates cerises mûres, coupées en quartiers","8 cm de concombre, haché","1 boîte de 400 g de pois chiches dans l'eau, égouttés (poids égoutté 240 g)","1 boîte de 200 g de thon dans l'eau, égoutté (poids égoutté 150 g)","150 g de feuilles de salade/laitue","2 quartiers de citron"],
["Mettez le zeste de citron dans un grand bol avec le poivre et l'huile d'olive.","Ajoutez ensuite l'oignon rouge, les tomates et le concombre, mélangez bien et laissez infuser quelques minutes.","Ajoutez les pois chiches et le thon, et incorporez délicatement afin que tout soit enrobé de vinaigrette.","Enfin, ajoutez les feuilles de salade, mélangez et répartissez entre deux boîtes à lunch, avec un quartier de citron à presser avant de manger."],
["Les ingrédients acides, comme le jus de citron, ramollissent votre salade : emportez donc un quartier de citron dans votre lunch pour l'utiliser juste avant de manger.","Le saumon ou les crevettes constituent une bonne alternative au thon. Pour une version végétalienne, essayez des morceaux de tofu mariné.",fv(4)]),
R(7055081,"Ragù de champignons",
"Un ragù de champignons riche, qui se marie à merveille avec des légumes en spirales.",
"2","358 g",
["1 cuillère à café d'huile de colza","1 poireau, finement tranché","250 g de champignons mélangés","2 gousses d'ail, tranchées très finement","1 pincée de flocons de piment","1 cuillère à café bombée d'origan séché","2 cuillères à café de graines de citrouille, grillées","2 cuillères à café de graines de tournesol, grillées","1 courgette, coupée en spirales","1 grosse carotte, coupée en spirales","2 cuillères à soupe de yogourt à 0 % de matières grasses","1 bon tour de moulin de poivre noir","5 g de copeaux de parmesan","brins de basilic frais, pour garnir"],
["Mettez l'huile dans une casserole et faites cuire doucement le poireau 3 à 4 minutes, en remuant régulièrement.","Ajoutez les champignons, l'ail, le piment et l'origan. Poursuivez la cuisson doucement 5 minutes, en remuant toujours régulièrement. Pendant ce temps, faites griller les graines et réservez.","Plongez les légumes en spirales (faits maison ou prêts à l'emploi) dans de l'eau bouillante pendant 2 minutes.","Juste avant de servir, incorporez le yogourt aux champignons.","Répartissez les légumes en spirales entre 2 bols. Garnissez chacun de sauce aux champignons, et saupoudrez de graines grillées, de poivre noir, de quelques copeaux de parmesan et d'un brin de basilic."],
["D'autres légumes en spirales se marient bien avec ce plat, comme la courge butternut ou la betterave.","Pour une option plus riche en glucides, servez avec des pâtes de grains entiers à la place des légumes en spirales.","Pour une alternative végétarienne au parmesan, remplacez-le par un fromage à pâte dure de type végétarien.","Vous pouvez utiliser un yogourt nature non sucré de votre choix, mais cela modifiera les valeurs nutritionnelles et la texture du plat.",fv(4)]),
R(7056258,"Écorce de yogourt glacé tutti frutti",
"Cette gâterie aux fruits est riche en vitamine C et constitue une excellente source de calcium.",
"4","246 g",
["500 g de yogourt grec à 0 % de matières grasses","2 cuillères à soupe d'édulcorant","1/2 barquette de framboises (environ 2 poignées)","1/2 barquette de fraises (environ 7), équeutées et coupées en quartiers","1 pêche moyenne, dénoyautée et finement tranchée","2 kiwis, pelés, coupés en deux et tranchés","20 g d'amandes effilées grillées"],
["Tapissez de papier sulfurisé un moule à gâteau roulé de 20 x 30 cm. Dans un grand bol, battez ensemble le yogourt grec et l'édulcorant, puis étalez dans le moule pour couvrir le fond.","Écrasez les framboises à la fourchette et arrosez-en le yogourt de façon aléatoire. Passez une brochette dans les framboises pour créer un motif en spirale. Parsemez du reste des fruits et des amandes effilées et faites congeler 3 à 4 heures, jusqu'à ce que ce soit pris.","Sortez du congélateur et laissez reposer 10 minutes avant de servir. Cassez en morceaux et servez immédiatement."],
[fv(1)]),
R(7059157,"Gruau aux abricots et graines grillées",
"Un plat réconfortant d'hiver, servi avec des graines et des fruits.",
"2","432 g",
["50 g d'abricots secs prêts à manger","150 ml de jus d'orange ou de pomme","50 g de flocons d'avoine","15 g de graines de chia ou de lin, grillées"],
["Mettez les abricots dans une petite casserole et couvrez-les de jus. Portez à ébullition et laissez mijoter 5 minutes.","Laissez reposer 10 minutes, puis mettez dans un robot culinaire ou un mélangeur et mixez pour obtenir une purée.","Mettez les flocons d'avoine dans une petite casserole, couvrez de 600 ml d'eau, puis placez à feu doux et faites cuire 3 à 4 minutes.","Incorporez la moitié de la purée d'abricots, répartissez entre 2 bols, puis garnissez de graines grillées et d'un tourbillon du reste de la purée."],
["Pour faire griller les graines, mettez-les dans une poêle sèche à feu moyen, remuez et retirez-les de la poêle dès qu'elles commencent à dorer.","Les graines ne sont pas essentielles à cette recette, mais elles constituent une bonne source d'acides gras oméga-3, qui contribuent à une bonne santé du cœur.","Se prépare aussi très bien avec des bleuets à la place des abricots.",fv(0)]),
R(7059382,"Moutabal aux oignons caramélisés",
"Des aubergines rôties avec des oignons, du tahini et de la coriandre, servies sur de jeunes feuilles de laitue, font une entrée ou une collation super saine.",
"4","257 g",
["2 aubergines (550 g)","2 cuillères à café d'huile de colza","3 oignons (200 g), finement hachés","2 cuillères à café de tahini (pâte de sésame)","le jus de 1/2 citron","1 gousse d'ail, écrasée","1 cuillère à soupe de yogourt faible en gras","15 g de coriandre fraîche, hachée","12 à 14 feuilles de laitue little gem","12 tomates cerises","1 petit piment rouge, tranché"],
["Préchauffez le four à 180 °C/thermostat 4. Lavez les aubergines, piquez-les plusieurs fois et placez-les entières sur une plaque de cuisson. Faites cuire au four 30 à 35 minutes, jusqu'à ce qu'elles soient tendres au toucher, puis sortez-les et laissez refroidir.","Pendant ce temps, mettez l'huile dans une casserole et faites chauffer les oignons lentement à feu doux pendant 25 minutes. Remuez fréquemment jusqu'à ce qu'ils soient tendres et commencent à dorer.","Retirez la chair des aubergines à la cuillère, puis mixez jusqu'à consistance lisse avec le tahini, le jus de citron, l'ail et le yogourt.","Incorporez les oignons et la coriandre.","Déposez dans les feuilles de laitue et disposez sur une assiette avec les tomates cerises, puis saupoudrez de piment."],
["Essayez avec différentes herbes, comme la menthe ou l'aneth.","Excellent à tartiner sur des sandwichs avec de la salade pour une collation rapide, ou comme trempette avec des crudités ou des languettes de pita de blé entier.",fv(2)]),
R(7060141,"Bhajis à l'oignon à la friteuse à air chaud",
"Cette recette de bhajis à l'oignon est meilleure que jamais, car nous avons utilisé une friteuse à air chaud pour obtenir ce croustillant authentique de « friture ». Cette recette a été sélectionnée en partenariat avec Slimming World.",
"10","72 g",
["50 g de farine de pois chiches","1 cuillère à café de garam masala","1/2 cuillère à café de paprika","1/2 cuillère à café de graines de fenouil, légèrement écrasées (facultatif)","1 gros oignon, coupé en quartiers et finement tranché","1 grosse carotte, grossièrement râpée","1 petite poignée de coriandre fraîche, finement hachée","enduit de cuisson en aérosol faible en calories",("Pour la trempette","250 g de yogourt de soja nature non sucré enrichi en calcium (ou voir le conseil)"),("Pour la trempette","2 grosses poignées de menthe fraîche hachée, plus un peu de menthe et quelques feuilles entières pour servir"),("Pour la trempette","1/2 à 1 piment vert, épépiné et finement haché")],
["Mettez la farine, le garam masala, le paprika, les graines de fenouil, le cas échéant, et un peu de poivre dans un grand bol. Ajoutez l'oignon, la carotte et la coriandre et mélangez bien. Incorporez 3 cuillères à soupe d'eau froide (ajoutez 1 à 2 cuillères à soupe de plus si nécessaire) et laissez reposer 5 minutes.","Préchauffez votre friteuse à air chaud à 180 °C.","Divisez le mélange en 10 portions égales, puis pressez chacune pour lui donner une petite forme de ballon de rugby. Vaporisez les bhajis d'enduit de cuisson faible en calories, puis mettez-en 5 dans le panier de votre friteuse à air chaud et faites cuire 8 à 10 minutes, ou jusqu'à ce qu'ils soient dorés et fermes. Transférez sur une assiette chaude, couvrez de papier d'aluminium et gardez au chaud pendant la cuisson des bhajis restants. Lorsque la deuxième fournée est prête, vous pouvez baisser la chaleur au minimum et remettre la première fournée 2 à 3 minutes pour la réchauffer.","Pendant la cuisson des bhajis, mélangez les ingrédients de la trempette. Servez les bhajis avec la trempette et parsemez le tout de menthe hachée et de feuilles supplémentaires.","Pour la cuisson au four : Faites cuire les bhajis sur une plaque de cuisson antiadhésive à 200 °C/chaleur tournante 180 °C/thermostat 6 pendant 10 à 15 minutes, ou jusqu'à ce qu'ils soient dorés et bien cuits."],
["Cette recette a été testée dans une friteuse à air chaud de 4.3 litres. Si la vôtre est plus grande, vous pourrez peut-être cuire tous les bhajis en même temps.","Si ces bhajis n'ont pas besoin d'être végétaliens, remplacez le yogourt de soja par du yogourt grec nature sans gras.","Cette recette donne 10 bhajis. Savourez-en quelques-uns en entrée ou servez-les en accompagnement d'un cari.",fv(0)]),
R(7064882,"Moules farcies à l'ail et aux petits pois, croûte de parmesan",
"Un plat impressionnant pour les fêtes, qui paraît plus compliqué qu'il ne l'est.",
"40","50 g",
["1 kilo de moules fraîches (pour obtenir 250 g de chair de moules)","1 cuillère à café d'huile","1 petit oignon rouge, finement haché","1 poivron rouge, finement haché","6 gousses d'ail, écrasées","80 g de petits pois surgelés, décongelés et écrasés","10 g de persil, finement haché","1 bonne pincée de poivre noir","50 g de chapelure (30 g pour la farce, 20 g pour le dessus)","20 g de parmesan, finement râpé."],
["Préchauffez le four à 190 °C/thermostat 5. Frottez très bien les moules et retirez les barbes. Jetez celles dont la coquille est abîmée et celles qui ne se ferment pas bien lorsqu'on les tapote sur le bord de l'évier. Rincez bien.","Mettez toutes les moules dans une casserole et couvrez avec un couvercle bien ajusté. Placez à feu vif et faites cuire 2 minutes, en secouant la casserole à mi-cuisson, jusqu'à ce que toutes les coquilles soient ouvertes à la vapeur, mais que les moules soient tout juste cuites. Jetez celles qui ne s'ouvrent pas. Versez dans une passoire au-dessus d'un bol et conservez le liquide.","Une fois légèrement refroidies, retirez les moules de leurs coquilles et réservez 40 demi-coquilles prêtes pour le service. Hachez les moules, puis réservez.","Mettez l'huile dans une casserole, ajoutez l'oignon et le poivron rouge et faites cuire à feu moyen 5 minutes. Ajoutez l'ail et faites cuire encore 2 minutes, en remuant régulièrement jusqu'à ce que ce soit tendre.","Ajoutez le liquide des moules et faites cuire 4 à 5 minutes, en remuant régulièrement, jusqu'à ce que le liquide soit presque complètement évaporé, puis retirez du feu.","Incorporez les moules hachées, les petits pois, le persil, le poivre noir et 30 g de chapelure.","Farcissez chaque moule d'une partie du mélange, en formant un petit dôme dans la coquille. Mélangez le reste de la chapelure et le parmesan et pressez-en un peu sur le dessus de chaque moule, en parsemant le reste sur les moules farcies.","Disposez sur une plaque de cuisson et faites cuire au four 15 minutes, jusqu'à ce que la farce soit d'un brun doré pâle et que les moules soient chaudes. Transférez les coquilles dans votre assiette de service et mangez immédiatement."],
["Vous pouvez préparer les légumes de la farce à l'avance et n'ajouter les moules qu'avant la cuisson."]),
R(7065016,"Tourte aux lentilles, aux fines herbes et au parmesan",
"Ce plat frais et rassasiant est riche en fibres et constitue une bonne source de glucides.",
"3","301 g",
[("Pour la pâte","100 g de farine nature"),("Pour la pâte","1 cuillère à soupe de fines herbes fraîches hachées"),("Pour la pâte","1 petit œuf, battu"),("Pour la pâte","2 cuillères à soupe d'huile d'olive"),("Pour la pâte","2 cuillères à soupe d'eau"),("Pour la garniture","1 cuillère à café d'huile d'olive"),("Pour la garniture","1 petit oignon, haché"),("Pour la garniture","1 gousse d'ail, écrasée"),("Pour la garniture","1/2 poivron rouge, haché"),("Pour la garniture","100 g de chou-fleur, coupé en bouquets"),("Pour la garniture","1 petite courgette, tranchée"),("Pour la garniture","1 branche de céleri, tranchée"),("Pour la garniture","1 petite carotte, râpée"),("Pour la garniture","50 g de lentilles rouges"),("Pour la garniture","1 boîte de 400 g de tomates hachées"),("Pour la garniture","200 ml de bouillon de légumes faible en sel"),("Pour la garniture","15 g de parmesan râpé"),("Pour la garniture","1 cuillère à soupe de fines herbes fraîches mélangées, hachées"),("Pour la garniture","poivre noir fraîchement moulu")],
["Préparez d'abord la pâte. Mettez la farine dans un bol et, à l'aide d'une fourchette, incorporez les herbes, l'œuf, l'huile d'olive et l'eau jusqu'à ce que la pâte se forme. Façonnez la pâte en boule et réfrigérez au moins 30 minutes.","Pendant ce temps, préchauffez le four à 200 ºC/thermostat 6 et préparez la garniture. Faites chauffer l'huile dans une grande poêle, ajoutez l'oignon, l'ail et le poivron et faites revenir trois minutes, jusqu'à ce qu'ils commencent à ramollir.","Ajoutez le chou-fleur, la courgette, le céleri et la carotte et poursuivez la cuisson trois minutes.","Ajoutez les lentilles, les tomates, le bouillon, le parmesan, les herbes et le poivre. Portez à ébullition et laissez mijoter 10 minutes, jusqu'à ce que les légumes soient presque cuits.","Transférez dans un plat à tarte. Abaissez la pâte et couvrez-en la tourte.","Faites cuire 25 à 30 minutes, jusqu'à ce que la pâte soit dorée et croustillante."],
["Vous pouvez en faire une version végétarienne en utilisant une alternative au parmesan ou un peu de fromage de chèvre végétarien.",FZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur ou au micro-ondes et réchauffez jusqu'à ce que ce soit bien chaud à cœur.",fv(3)]),
R(7066965,"Pizza aux légumes",
"Variez les garnitures et créez votre propre pizza végétarienne.",
"4","292 g",
["1 cuillère à soupe d'huile d'olive","1 gros oignon rouge, coupé en deux puis tranché","1 poivron rouge et 1 poivron jaune, épépinés et coupés en morceaux","100 g de champignons, tranchés","1 cuillère à café rase de basilic séché","1 cuillère à café bombée d'origan séché","3 à 4 gousses d'ail, écrasées","2 bons tours de moulin de poivre noir","4 tomates séchées, finement hachées","2 à 3 tomates fraîches, hachées","2 grands pains naan nature (130 g chacun)","1 boule de 125 g à teneur réduite en gras","mozzarella, finement tranchée","8 à 10 feuilles de basilic frais, pour servir"],
["Préchauffez le four à 200 °C/thermostat 6. Mettez l'huile d'olive dans la poêle avec l'oignon et faites cuire 2 minutes. Ajoutez ensuite les poivrons et les champignons, et remuez régulièrement 7 à 8 minutes, en veillant à ce qu'ils cuisent uniformément.","Ajoutez le basilic, l'origan, l'ail, un tour de moulin de poivre noir, les tomates séchées et les tomates fraîches. Mélangez bien, portez à ébullition, puis réduisez le feu, couvrez et laissez mijoter doucement 5 minutes.","Placez les pains naan sur une plaque de cuisson et répartissez uniformément les légumes et la mozzarella par-dessus. Faites cuire au four environ 8 à 10 minutes (jusqu'à ce que le fromage soit fondu et que les bords du naan soient légèrement dorés).","Saupoudrez de feuilles de basilic frais et de poivre noir avant de servir."],
["En faisant d'abord cuire vos légumes, vous pouvez en mettre beaucoup plus sur votre pizza. Cela donne un repas plus sain et plus savoureux.","Vous pouvez garder quelques pains naan au congélateur et utiliser différentes combinaisons de légumes, même des restes. Si vous n'avez pas de mozzarella à teneur réduite en gras, un cheddar à teneur réduite en gras convient bien.",FZ+"congelez dans du papier sulfurisé. Décongelez 1 heure, puis faites cuire normalement.",fv(2)]),
R(7067962,"Ragoût d'agneau et de haricots blancs",
"Un plat campagnard consistant, facile à préparer et très rassasiant. Vous pouvez aussi congeler les restes.",
"4","423 g",
["huile d'olive en aérosol","300 g d'agneau très maigre, coupé en dés","1 oignon, grossièrement haché","2 branches de céleri, coupées en morceaux de 2 cm","2 carottes, pelées et coupées en morceaux de 2 cm","2 gousses d'ail, tranchées","2 branches de romarin","1 cuillère à soupe de sauce Worcestershire","1 boîte de 410 g de tomates hachées","2 feuilles de laurier","1 boîte de 820 g de haricots à œil noir dans l'eau, égouttés et rincés","300 g de chou frisé de Savoie, grossièrement haché","poivre noir moulu"],
["Préchauffez le four à 180 ºC/thermostat 4.","Faites chauffer une cocotte allant sur le feu à feu vif, vaporisez-la légèrement d'huile d'olive et faites dorer l'agneau par lots, de tous les côtés. Réservez.","Dans la même cocotte, ajoutez l'oignon, le céleri, les carottes, l'ail et le romarin et faites cuire, en ajoutant un filet d'eau, jusqu'à ce que les légumes commencent à ramollir (environ 10 minutes).","Remettez l'agneau dans la cocotte et ajoutez la sauce Worcestershire, les tomates et les feuilles de laurier. Mélangez et ajoutez 300 ml d'eau.","Couvrez et faites cuire au four 45 minutes. Incorporez les haricots et le chou, en ajoutant de l'eau au besoin.","Remettez au four encore 15 minutes."],
["Vous pouvez préparer ce plat avec du porc maigre ou du bœuf.","Essayez d'autres haricots, comme les borlotti, les cannellini ou les haricots blancs.",FZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur ou au micro-ondes et réchauffez au four ou au micro-ondes jusqu'à ce que ce soit bien chaud.",fv(4)]),
]
save(3,recs)
